import type { ClaraDomainOption } from 'components/ai/components/molecules/ClaraDomainDropdown';
import {
  CLARA_BRAND_GUIDANCE_PROJECT_KEY,
  CLARA_CATEGORY_PROJECT_KEY,
  CLARA_CONSUMER_PROJECT_KEY,
  CLARA_VALUE_CREATION_PROJECT_KEY,
} from 'components/ai/constants/projectKeys';
import { APP_BASENAME } from 'config/api';

export type ClaraDomainPillar =
  | 'valueCreation'
  | 'portfolioBrand'
  | 'category'
  | 'consumer'
  | 'connectionsCreativity'
  | 'innovation'
  | 'tradeExecution';

export type ClaraDomainStateKey = ClaraDomainPillar | 'legacy';

export type ClaraDomainRouteDefault = {
  key: ClaraDomainPillar;
  path: string;
  defaultValue: string;
};

const LEGACY_STATE_KEY = 'legacy';

export const LEGACY_CLARA_DOMAIN_VALUE = CLARA_BRAND_GUIDANCE_PROJECT_KEY;

export const CLARA_DOMAIN_ROUTE_DEFAULTS: ClaraDomainRouteDefault[] = [
  {
    key: 'valueCreation',
    path: '/value-creation',
    defaultValue: CLARA_VALUE_CREATION_PROJECT_KEY,
  },
  {
    key: 'portfolioBrand',
    path: '/portfolio-brand',
    defaultValue: CLARA_BRAND_GUIDANCE_PROJECT_KEY,
  },
  {
    key: 'category',
    path: '/category',
    defaultValue: CLARA_CATEGORY_PROJECT_KEY,
  },
  {
    key: 'consumer',
    path: '/consumer',
    defaultValue: CLARA_CONSUMER_PROJECT_KEY,
  },
  {
    key: 'connectionsCreativity',
    path: '/connections-creativity',
    defaultValue: CLARA_BRAND_GUIDANCE_PROJECT_KEY,
  },
  {
    key: 'innovation',
    path: '/innovation',
    defaultValue: CLARA_BRAND_GUIDANCE_PROJECT_KEY,
  },
  {
    key: 'tradeExecution',
    path: '/trade-execution',
    defaultValue: CLARA_BRAND_GUIDANCE_PROJECT_KEY,
  },
];

export const LEGACY_CLARA_DOMAIN_OPTION: ClaraDomainOption = {
  label: 'Clara: Brand Guidance',
  value: LEGACY_CLARA_DOMAIN_VALUE,
  description: '',
};

export const buildInitialDomainByRoute = (): Record<
  ClaraDomainStateKey,
  string
> => {
  return CLARA_DOMAIN_ROUTE_DEFAULTS.reduce(
    (defaults, route) => ({
      ...defaults,
      [route.key]: route.defaultValue,
    }),
    {
      [LEGACY_STATE_KEY]: LEGACY_CLARA_DOMAIN_VALUE,
    } as Record<ClaraDomainStateKey, string>,
  );
};

const normalizePathname = (pathname: string) => {
  if (!pathname || pathname === '/') return '/';

  let pathnameOnly = pathname.split('?')[0].split('#')[0];

  if (pathnameOnly.startsWith(APP_BASENAME)) {
    pathnameOnly = pathnameOnly.slice(APP_BASENAME.length) || '/';
  }

  if (pathnameOnly.length > 1 && pathnameOnly.endsWith('/')) {
    return pathnameOnly.slice(0, -1);
  }

  return pathnameOnly;
};

const matchesRoutePath = (pathname: string, routePath: string) => {
  return pathname === routePath || pathname.startsWith(`${routePath}/`);
};

export const isOptionAvailable = (
  value: string,
  options: ClaraDomainOption[],
): boolean => options.some((option) => option.value === value);

export const getClaraDomainRouteDefault = (pathname: string) => {
  const normalizedPathname = normalizePathname(pathname);

  return CLARA_DOMAIN_ROUTE_DEFAULTS.find((route) =>
    matchesRoutePath(normalizedPathname, route.path),
  );
};

export const getRouteDefaultValue = (
  key: ClaraDomainPillar,
  isValueCreationPillarEnabled: boolean,
): string => {
  if (key === 'consumer') return CLARA_CONSUMER_PROJECT_KEY;

  if (key === 'valueCreation') {
    return isValueCreationPillarEnabled
      ? CLARA_VALUE_CREATION_PROJECT_KEY
      : LEGACY_CLARA_DOMAIN_VALUE;
  }

  if (key === 'category') return CLARA_CATEGORY_PROJECT_KEY;

  return CLARA_BRAND_GUIDANCE_PROJECT_KEY;
};

export const getDefaultClaraDomainValue = (
  pathname: string,
  isValueCreationPillarEnabled = false,
) => {
  const routeDefault = getClaraDomainRouteDefault(pathname);

  if (!routeDefault) return LEGACY_CLARA_DOMAIN_VALUE;

  return getRouteDefaultValue(routeDefault.key, isValueCreationPillarEnabled);
};

export const resolveRouteDefaultValue = (
  stateKey: ClaraDomainStateKey,
  routeDefault: ClaraDomainRouteDefault | undefined,
  isValueCreationPillarEnabled: boolean,
  lastSelectedValue: string,
  options: ClaraDomainOption[],
): string => {
  if (stateKey === LEGACY_STATE_KEY) return LEGACY_CLARA_DOMAIN_VALUE;

  if (stateKey === 'valueCreation' && !isValueCreationPillarEnabled) {
    if (isOptionAvailable(lastSelectedValue, options)) {
      return lastSelectedValue;
    }

    return LEGACY_CLARA_DOMAIN_VALUE;
  }

  if (routeDefault) {
    return getRouteDefaultValue(routeDefault.key, isValueCreationPillarEnabled);
  }

  return LEGACY_CLARA_DOMAIN_VALUE;
};
